import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第十六卦豫 雷地豫 震上坤下","description":"周易 - 第十六卦豫 雷地豫 震上坤下","frontmatter":{"title":"第十六卦豫 雷地豫 震上坤下","description":"周易 - 第十六卦豫 雷地豫 震上坤下"},"headers":[],"relativePath":"classics/zhouyi/017.md","filePath":"classics/zhouyi/017.md"}'),l={name:"classics/zhouyi/017.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="雷地豫" tabindex="-1">雷地豫 <a class="header-anchor" href="#雷地豫" aria-label="Permalink to “雷地豫”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>利建侯行師。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>豫，剛應而志行，順以動，豫。豫，順以動，故天地如之，而況建侯行師乎？天地以順動，故日月不過，而四時不忒；聖人以順動，則刑罰清而民服。豫之時義大矣哉！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>鳴豫，兇。象 曰：初六鳴豫，志窮兇也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>介於石，不終日，貞吉。象曰：不終日，貞吉；以中正也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>盱豫，悔。遲有悔。象曰：盱豫有悔，位不當也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>由豫，大有得。勿疑。朋盍簪。象曰：由豫，大有得；志大行也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>貞疾，恆不死。象曰：六五貞疾，乘剛也。恆不死，中未亡也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>冥豫，成有渝，無咎。象曰：冥豫在上，何可長也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
